package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.persistence.mapper.*;import java.util.*;import java.time.*;import java.util.function.Function;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual author/consumer/schema running against stateful database-boundary doubles. */
public class RuntimeRetentionAuthorTest extends RuntimeRetentionAuthorFixture {
 public RuntimeRetentionAuthorTest()throws Exception{super();}
 @Test void actualCreateReplayAndReadOnlyRecovery()throws Exception{within(()->{var saved=service.approve(actor,"1","new-original-key-123",bytes(request));assertEquals(saved,service.approve(actor,"1","new-original-key-123",bytes(request)));assertEquals(saved,service.recover(actor,"1","new-original-key-123").required("receipt"));verify(mapper,times(1)).insertPolicy(anyMap());assertEquals("IN_EFFECT",reads.read(actor,"1",saved.required("policy_revision").textValue()).required("lifecycle").asText());});}
 @Test void changedOriginalBodyRejectsReplay()throws Exception{within(()->{service.approve(actor,"1","new-original-key-123",bytes(request));request.put("reason","changed");assertThrows(TenantAccessException.class,()->service.approve(actor,"1","new-original-key-123",bytes(request)));});}
 @Test void disableIsImmutableAndStopsSelection()throws Exception{within(()->{var body=bytes(retirementRequest());var saved=retirement.retire(actor,"1","retirement-key-123",body);assertEquals(saved,retirement.retire(actor,"1","retirement-key-123",body));assertEquals(saved,retirement.recover(actor,"1","retirement-key-123").required("receipt"));assertEquals("RETIRED",reads.read(actor,"1",id(4)).required("lifecycle").asText());assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION"));verify(mapper,times(1)).insertRetirement(anyMap());});}
 @Test void scheduledReplacementRetainsOldUntilExactBoundary()throws Exception{within(()->{request.put("effective_from",now.plusHours(1).toInstant(ZoneOffset.UTC).toString());request.set("replaces",json.object().put("policy_revision",id(4)).put("expected_revision","1"));var saved=service.approve(actor,"1","replace-original-key",bytes(request));assertEquals("IN_EFFECT",reads.read(actor,"1",id(4)).required("lifecycle").asText());assertEquals("SCHEDULED",reads.read(actor,"1",saved.required("policy_revision").asText()).required("lifecycle").asText());when(permissions.databaseTime()).thenReturn(now.plusHours(1));assertEquals("RETIRED",reads.read(actor,"1",id(4)).required("lifecycle").asText());assertEquals("IN_EFFECT",reads.read(actor,"1",saved.required("policy_revision").asText()).required("lifecycle").asText());});}
 @Test void missingRetirementEvidenceFailsClosed()throws Exception{within(()->{retirement.retire(actor,"1","retirement-key-123",bytes(retirementRequest()));decisions.clear();assertThrows(TenantAccessException.class,()->reads.read(actor,"1",id(4)));});}
 @Test void boundedListingUsesActualFixedRows()throws Exception{within(()->{var out=reads.list(actor,"1","PROJECT",id(3),1,null);assertEquals(1,out.required("items").size());assertTrue(out.required("complete").asBoolean());assertEquals(id(4),out.at("/items/0/fixed/policy_revision").asText());assertThrows(SchemaRejection.class,()->reads.list(actor,"1","ENTERPRISE",id(3),1,null));});}
 @Test void staleContextAndDeniedReadDoNotWrite()throws Exception{within(()->{assertThrows(TenantAccessException.class,()->service.approve(actor,"2","new-original-key-123",bytes(request)));when(resources.require(eq(a),any(),eq("retention.read"),eq("RUNTIME_RETENTION_READING"))).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->reads.list(actor,"1","PROJECT",id(3),1,null));verify(mapper,never()).insertPolicy(anyMap());});}
 @Test void retiredMetadataTamperingRejects()throws Exception{within(()->{retirement.retire(actor,"1","retirement-key-123",bytes(retirementRequest()));var old=states.get(id(4));for(String mutation:List.of("schema","classification","updatedAt")){states.put(id(4),new RuntimeRetentionMapper.State(old.tenantId(),old.projectId(),old.policyRevision(),old.retiredAt(),old.decisionId(),old.revision(),mutation.equals("schema")?"9.0.0":old.schemaVersion(),old.manifest(),mutation.equals("classification")?"PUBLIC":old.classification(),old.createdBy(),old.createdAt(),mutation.equals("updatedAt")?now.plusSeconds(1).toInstant(ZoneOffset.UTC).toString():old.updatedAt()));assertThrows(TenantAccessException.class,()->reads.read(actor,"1",id(4)));}states.put(id(4),old);});}
 @Test void readRecoverySurvivesRemovedWriteGrantAndSessionChange()throws Exception{within(()->{var saved=service.approve(actor,"1","new-original-key-123",bytes(request));when(actor.sessionId()).thenReturn("new-session");when(resources.require(eq(a),any(),eq("retention.approve"),eq("RUNTIME_RETENTION_APPROVAL"))).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertEquals(saved,service.recover(actor,"1","new-original-key-123").required("receipt"));assertThrows(TenantAccessException.class,()->service.approve(actor,"1","new-original-key-123",bytes(request)));});}
 @Test void foreignActorCannotRecoverOriginalKey()throws Exception{within(()->{service.approve(actor,"1","new-original-key-123",bytes(request));when(a.actorId()).thenReturn(id(99));assertEquals("NOT_FOUND",service.recover(actor,"1","new-original-key-123").required("status").asText());});}
 @Test void originalLifecycleProofRejectsLaterScheduledRetirement()throws Exception{within(()->{var proof=authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION");var r=retirementRequest().put("effective_at",now.plusHours(1).toInstant(ZoneOffset.UTC).toString());retirement.retire(actor,"1","retirement-key-123",bytes(r));assertThrows(TenantAccessException.class,proof::requireUnchanged);});}
 @Test void recomputedPrivateDecisionHashCannotForgeIndependentWitness()throws Exception{within(()->{retirement.retire(actor,"1","retirement-key-123",bytes(retirementRequest()));var old=decisions.values().iterator().next();var forged=(ObjectNode)schema.read(old.fixedJson());((ObjectNode)forged.required("authority_grant")).put("grant_id",id(88));decisions.put(old.decisionId(),new RuntimeRetentionMapper.Retirement(old.tenantId(),old.projectId(),old.decisionId(),old.policyRevision(),schema.canonical(forged),schema.hash(forged),old.operationId(),old.key(),old.createdBy(),old.createdAt(),old.schemaVersion(),old.manifest(),old.classification()));assertThrows(TenantAccessException.class,()->reads.read(actor,"1",id(4)));});}
 @Test void changedRetirementReasonAndMismatchedTypedReceiptReject()throws Exception{within(()->{retirement.retire(actor,"1","retirement-key-123",bytes(retirementRequest()));var old=decisions.values().iterator().next();for(String field:List.of("reason","receipt")){var forged=(ObjectNode)schema.read(old.fixedJson());if(field.equals("reason"))((ObjectNode)forged.required("original_request")).put("reason","forged reason");else ((ObjectNode)forged.required("operation_receipt")).put("decision_id",id(88));var row=new RuntimeRetentionMapper.Retirement(old.tenantId(),old.projectId(),old.decisionId(),old.policyRevision(),schema.canonical(forged),schema.hash(forged),old.operationId(),old.key(),old.createdBy(),old.createdAt(),old.schemaVersion(),old.manifest(),old.classification());assertThrows(RuntimeException.class,()->authority.verifyRetirement(row));}});}
 @Test void originalSessionContextAndKeyAreExternallyAnchored()throws Exception{within(()->{var original=policies.get(id(4));for(String field:List.of("session","context","key")){String context=original.contextJson();if(field.equals("context")){var c=(ObjectNode)schema.read(context);c.put("auth_epoch","2");context=schema.canonical(c);}var changed=new RuntimeRetentionMapper.Row(original.tenantId(),original.projectId(),original.policyRevision(),original.fixedJson(),original.requestJson(),original.requestHash(),original.contentHash(),original.operationId(),field.equals("key")?"changed-original-key":original.key(),original.creator(),original.createdAt(),original.classification(),original.schemaVersion(),original.manifest(),original.auditId(),original.eventId(),original.receiptJson(),field.equals("session")?"other-session":original.sessionId(),context);assertThrows(TenantAccessException.class,()->authority.verify(changed));}});}
 @Test void realBusinessClassificationSupportsPersonalHealthAndRejectsConfidential()throws Exception{within(()->{request.put("classification","PERSONAL_HEALTH");var receipt=service.approve(actor,"1","personal-health-approval",bytes(request));String id=receipt.required("policy_revision").asText();assertEquals("PERSONAL_HEALTH",policies.get(id).classification());assertEquals(id,authority.require(a,id,id(3),"PERSONAL_HEALTH","RUN_CREATION").policyRevision());request.put("classification","CONFIDENTIAL");clearInvocations(mapper);assertThrows(SchemaRejection.class,()->service.approve(actor,"1","invalid-classification",bytes(request)));verify(mapper,never()).insertPolicy(anyMap());});}
 public static void main(String[]args)throws Exception{int n=0;for(var m:RuntimeRetentionAuthorTest.class.getDeclaredMethods())if(m.isAnnotationPresent(Test.class)){try{m.invoke(new RuntimeRetentionAuthorTest());System.out.println("PASS "+m.getName());n++;}catch(java.lang.reflect.InvocationTargetException e){throw new RuntimeException(m.getName(),e.getCause());}}System.out.println("PASS "+n+" author tests");}
}
